INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361233661952, 'Playwright', '0.0.26', 'browser_console_messages', 'Returns all console messages', '{"type":"object","properties":{},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.902513', 'admin', '2025-05-23 16:53:01.902513', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361246244864, 'Playwright', '0.0.26', 'browser_handle_dialog', 'Handle a dialog', '{"type":"object","properties":{"accept":{"type":"boolean","description":"Whether to accept the dialog."},"promptText":{"type":"string","description":"The text of the prompt in case of a prompt dialog."}},"required":["accept"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.906542', 'admin', '2025-05-23 16:53:01.906542', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361254633472, 'Playwright', '0.0.26', 'browser_file_upload', 'Upload one or multiple files', '{"type":"object","properties":{"paths":{"type":"array","items":{"type":"string"},"description":"The absolute paths to the files to upload. Can be a single file or multiple files."}},"required":["paths"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.908772', 'admin', '2025-05-23 16:53:01.908772', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361267216384, 'Playwright', '0.0.26', 'browser_install', 'Install the browser specified in the config. Call this if you get an error about the browser not being installed.', '{"type":"object","properties":{},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.910907', 'admin', '2025-05-23 16:53:01.910907', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361275604992, 'Playwright', '0.0.26', 'browser_press_key', 'Press a key on the keyboard', '{"type":"object","properties":{"key":{"type":"string","description":"Name of the key to press or a character to generate, such as \u0060ArrowLeft\u0060 or \u0060a\u0060"}},"required":["key"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.912925', 'admin', '2025-05-23 16:53:01.912925', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361283993600, 'Playwright', '0.0.26', 'browser_navigate', 'Navigate to a URL', '{"type":"object","properties":{"url":{"type":"string","description":"The URL to navigate to"}},"required":["url"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.915081', 'admin', '2025-05-23 16:53:01.915081', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361292382208, 'Playwright', '0.0.26', 'browser_navigate_back', 'Go back to the previous page', '{"type":"object","properties":{},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.917439', 'admin', '2025-05-23 16:53:01.917439', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361300770816, 'Playwright', '0.0.26', 'browser_navigate_forward', 'Go forward to the next page', '{"type":"object","properties":{},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.919773', 'admin', '2025-05-23 16:53:01.919773', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361313353728, 'Playwright', '0.0.26', 'browser_network_requests', 'Returns all network requests since loading the page', '{"type":"object","properties":{},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.921995', 'admin', '2025-05-23 16:53:01.921995', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361321742336, 'Playwright', '0.0.26', 'browser_pdf_save', 'Save page as PDF', '{"type":"object","properties":{"filename":{"type":"string","description":"File name to save the pdf to. Defaults to \u0060page-{timestamp}.pdf\u0060 if not specified."}},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.92424', 'admin', '2025-05-23 16:53:01.92424', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361330130944, 'Playwright', '0.0.26', 'browser_take_screenshot', 'Take a screenshot of the current page. You can''t perform actions based on the screenshot, use browser_snapshot for actions.', '{"type":"object","properties":{"raw":{"type":"boolean","description":"Whether to return without compression (in PNG format). Default is false, which returns a JPEG image."},"filename":{"type":"string","description":"File name to save the screenshot to. Defaults to \u0060page-{timestamp}.{png|jpeg}\u0060 if not specified."},"element":{"type":"string","description":"Human-readable element description used to obtain permission to screenshot the element. If not provided, the screenshot will be taken of viewport. If element is provided, ref must be provided too."},"ref":{"type":"string","description":"Exact target element reference from the page snapshot. If not provided, the screenshot will be taken of viewport. If ref is provided, element must be provided too."}},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.926429', 'admin', '2025-05-23 16:53:01.926429', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361342713856, 'Playwright', '0.0.26', 'browser_snapshot', 'Capture accessibility snapshot of the current page, this is better than screenshot', '{"type":"object","properties":{},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.928814', 'admin', '2025-05-23 16:53:01.928814', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361351102464, 'Playwright', '0.0.26', 'browser_click', 'Perform click on a web page', '{"type":"object","properties":{"element":{"type":"string","description":"Human-readable element description used to obtain permission to interact with the element"},"ref":{"type":"string","description":"Exact target element reference from the page snapshot"}},"required":["element","ref"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.931138', 'admin', '2025-05-23 16:53:01.931138', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361359491072, 'Playwright', '0.0.26', 'browser_drag', 'Perform drag and drop between two elements', '{"type":"object","properties":{"startElement":{"type":"string","description":"Human-readable source element description used to obtain the permission to interact with the element"},"startRef":{"type":"string","description":"Exact source element reference from the page snapshot"},"endElement":{"type":"string","description":"Human-readable target element description used to obtain the permission to interact with the element"},"endRef":{"type":"string","description":"Exact target element reference from the page snapshot"}},"required":["startElement","startRef","endElement","endRef"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.933438', 'admin', '2025-05-23 16:53:01.933438', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361367879680, 'Playwright', '0.0.26', 'browser_hover', 'Hover over element on page', '{"type":"object","properties":{"element":{"type":"string","description":"Human-readable element description used to obtain permission to interact with the element"},"ref":{"type":"string","description":"Exact target element reference from the page snapshot"}},"required":["element","ref"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.935528', 'admin', '2025-05-23 16:53:01.935528', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361376268288, 'Playwright', '0.0.26', 'browser_type', 'Type text into editable element', '{"type":"object","properties":{"element":{"type":"string","description":"Human-readable element description used to obtain permission to interact with the element"},"ref":{"type":"string","description":"Exact target element reference from the page snapshot"},"text":{"type":"string","description":"Text to type into the element"},"submit":{"type":"boolean","description":"Whether to submit entered text (press Enter after)"},"slowly":{"type":"boolean","description":"Whether to type one character at a time. Useful for triggering key handlers in the page. By default entire text is filled in at once."}},"required":["element","ref","text"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.93738', 'admin', '2025-05-23 16:53:01.93738', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361384656896, 'Playwright', '0.0.26', 'browser_select_option', 'Select an option in a dropdown', '{"type":"object","properties":{"element":{"type":"string","description":"Human-readable element description used to obtain permission to interact with the element"},"ref":{"type":"string","description":"Exact target element reference from the page snapshot"},"values":{"type":"array","items":{"type":"string"},"description":"Array of values to select in the dropdown. This can be a single value or multiple values."}},"required":["element","ref","values"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.939185', 'admin', '2025-05-23 16:53:01.939185', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361401434112, 'Playwright', '0.0.26', 'browser_tab_new', 'Open a new tab', '{"type":"object","properties":{"url":{"type":"string","description":"The URL to navigate to in the new tab. If not provided, the new tab will be blank."}},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.943169', 'admin', '2025-05-23 16:53:01.943169', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361418211328, 'Playwright', '0.0.26', 'browser_tab_close', 'Close a tab', '{"type":"object","properties":{"index":{"type":"number","description":"The index of the tab to close. Closes current tab if not provided."}},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.947318', 'admin', '2025-05-23 16:53:01.947318', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361434988544, 'Playwright', '0.0.26', 'browser_wait_for', 'Wait for text to appear or disappear or a specified time to pass', '{"type":"object","properties":{"time":{"type":"number","description":"The time to wait in seconds"},"text":{"type":"string","description":"The text to wait for"},"textGone":{"type":"string","description":"The text to wait for to disappear"}},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.951594', 'admin', '2025-05-23 16:53:01.951594', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837469048246272, 'memory-server', '0.6.3', 'create_relations', 'Create multiple new relations between entities in the knowledge graph. Relations should be in active voice', '{"type":"object","properties":{"relations":{"type":"array","items":{"type":"object","properties":{"from":{"type":"string","description":"The name of the entity where the relation starts"},"to":{"type":"string","description":"The name of the entity where the relation ends"},"relationType":{"type":"string","description":"The type of the relation"}},"required":["from","to","relationType"]}}},"required":["relations"]}', '2025-05-23 16:53:27.608156', 'admin', '2025-05-23 16:53:27.608156', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837469065023488, 'memory-server', '0.6.3', 'delete_entities', 'Delete multiple entities and their associated relations from the knowledge graph', '{"type":"object","properties":{"entityNames":{"type":"array","items":{"type":"string"},"description":"An array of entity names to delete"}},"required":["entityNames"]}', '2025-05-23 16:53:27.612694', 'admin', '2025-05-23 16:53:27.612694', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837469085995008, 'memory-server', '0.6.3', 'delete_relations', 'Delete multiple relations from the knowledge graph', '{"type":"object","properties":{"relations":{"type":"array","items":{"type":"object","properties":{"from":{"type":"string","description":"The name of the entity where the relation starts"},"to":{"type":"string","description":"The name of the entity where the relation ends"},"relationType":{"type":"string","description":"The type of the relation"}},"required":["from","to","relationType"]},"description":"An array of relations to delete"}},"required":["relations"]}', '2025-05-23 16:53:27.617777', 'admin', '2025-05-23 16:53:27.617777', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837469102772224, 'memory-server', '0.6.3', 'search_nodes', 'Search for nodes in the knowledge graph based on a query', '{"type":"object","properties":{"query":{"type":"string","description":"The search query to match against entity names, types, and observation content"}},"required":["query"]}', '2025-05-23 16:53:27.621784', 'admin', '2025-05-23 16:53:27.621784', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837508722167808, 'mcp-git', '1.9.1', 'git_diff_unstaged', 'Shows changes in the working directory that are not yet staged', '{"properties":{"repo_path":{"title":"Repo Path","type":"string"}},"required":["repo_path"],"title":"GitDiffUnstaged","type":"object"}', '2025-05-23 16:53:37.067452', 'admin', '2025-05-23 16:53:37.067452', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837508747333632, 'mcp-git', '1.9.1', 'git_diff', 'Shows differences between branches or commits', '{"properties":{"repo_path":{"title":"Repo Path","type":"string"},"target":{"title":"Target","type":"string"}},"required":["repo_path","target"],"title":"GitDiff","type":"object"}', '2025-05-23 16:53:37.073028', 'admin', '2025-05-23 16:53:37.073028', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837508768305152, 'mcp-git', '1.9.1', 'git_add', 'Adds file contents to the staging area', '{"properties":{"repo_path":{"title":"Repo Path","type":"string"},"files":{"items":{"type":"string"},"title":"Files","type":"array"}},"required":["repo_path","files"],"title":"GitAdd","type":"object"}', '2025-05-23 16:53:37.078318', 'admin', '2025-05-23 16:53:37.078318', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837508797665280, 'mcp-git', '1.9.1', 'git_log', 'Shows the commit logs', '{"properties":{"repo_path":{"title":"Repo Path","type":"string"},"max_count":{"default":10,"title":"Max Count","type":"integer"}},"required":["repo_path"],"title":"GitLog","type":"object"}', '2025-05-23 16:53:37.084798', 'admin', '2025-05-23 16:53:37.084798', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837508822831104, 'mcp-git', '1.9.1', 'git_checkout', 'Switches branches', '{"properties":{"repo_path":{"title":"Repo Path","type":"string"},"branch_name":{"title":"Branch Name","type":"string"}},"required":["repo_path","branch_name"],"title":"GitCheckout","type":"object"}', '2025-05-23 16:53:37.091406', 'admin', '2025-05-23 16:53:37.091406', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541429350400, 'Notion MCP Server', '1.0.0', 'notion_retrieve_block', 'Retrieve a block from Notion', '{"type":"object","properties":{"block_id":{"type":"string","description":"The ID of the block to retrieve.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["block_id"]}', '2025-05-23 16:53:44.86471', 'admin', '2025-05-23 16:53:44.86471', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541513236480, 'Notion MCP Server', '1.0.0', 'notion_delete_block', 'Delete a block in Notion', '{"type":"object","properties":{"block_id":{"type":"string","description":"The ID of the block to delete.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["block_id"]}', '2025-05-23 16:53:44.884962', 'admin', '2025-05-23 16:53:44.884962', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541546790912, 'Notion MCP Server', '1.0.0', 'notion_retrieve_page', 'Retrieve a page from Notion', '{"type":"object","properties":{"page_id":{"type":"string","description":"The ID of the page to retrieve.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["page_id"]}', '2025-05-23 16:53:44.89341', 'admin', '2025-05-23 16:53:44.89341', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361393045504, 'Playwright', '0.0.26', 'browser_tab_list', 'List browser tabs', '{"type":"object","properties":{},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.94125', 'admin', '2025-05-23 16:53:01.94125', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361409822720, 'Playwright', '0.0.26', 'browser_tab_select', 'Select a tab by index', '{"type":"object","properties":{"index":{"type":"number","description":"The index of the tab to select"}},"required":["index"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.945044', 'admin', '2025-05-23 16:53:01.945044', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837361426599936, 'Playwright', '0.0.26', 'browser_generate_playwright_test', 'Generate a Playwright test for given scenario', '{"type":"object","properties":{"name":{"type":"string","description":"The name of the test"},"description":{"type":"string","description":"The description of the test"},"steps":{"type":"array","items":{"type":"string"},"description":"The steps of the test"}},"required":["name","description","steps"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:01.949522', 'admin', '2025-05-23 16:53:01.949522', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837469027274752, 'memory-server', '0.6.3', 'create_entities', 'Create multiple new entities in the knowledge graph', '{"type":"object","properties":{"entities":{"type":"array","items":{"type":"object","properties":{"name":{"type":"string","description":"The name of the entity"},"entityType":{"type":"string","description":"The type of the entity"},"observations":{"type":"array","items":{"type":"string"},"description":"An array of observation contents associated with the entity"}},"required":["name","entityType","observations"]}}},"required":["entities"]}', '2025-05-23 16:53:27.603446', 'admin', '2025-05-23 16:53:27.603446', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837469056634880, 'memory-server', '0.6.3', 'add_observations', 'Add new observations to existing entities in the knowledge graph', '{"type":"object","properties":{"observations":{"type":"array","items":{"type":"object","properties":{"entityName":{"type":"string","description":"The name of the entity to add the observations to"},"contents":{"type":"array","items":{"type":"string"},"description":"An array of observation contents to add"}},"required":["entityName","contents"]}}},"required":["observations"]}', '2025-05-23 16:53:27.610694', 'admin', '2025-05-23 16:53:27.610694', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837469077606400, 'memory-server', '0.6.3', 'delete_observations', 'Delete specific observations from entities in the knowledge graph', '{"type":"object","properties":{"deletions":{"type":"array","items":{"type":"object","properties":{"entityName":{"type":"string","description":"The name of the entity containing the observations"},"observations":{"type":"array","items":{"type":"string"},"description":"An array of observations to delete"}},"required":["entityName","observations"]}}},"required":["deletions"]}', '2025-05-23 16:53:27.615267', 'admin', '2025-05-23 16:53:27.615267', 'admin');
