INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837469111160832, 'memory-server', '0.6.3', 'open_nodes', 'Open specific nodes in the knowledge graph by their names', '{"type":"object","properties":{"names":{"type":"array","items":{"type":"string"},"description":"An array of entity names to retrieve"}},"required":["names"]}', '2025-05-23 16:53:27.623906', 'admin', '2025-05-23 16:53:27.623906', 'admin');
