INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837508755722240, 'mcp-git', '1.9.1', 'git_commit', 'Records changes to the repository', '{"properties":{"repo_path":{"title":"Repo Path","type":"string"},"message":{"title":"Message","type":"string"}},"required":["repo_path","message"],"title":"GitCommit","type":"object"}', '2025-05-23 16:53:37.075653', 'admin', '2025-05-23 16:53:37.075653', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837508780888064, 'mcp-git', '1.9.1', 'git_reset', 'Unstages all staged changes', '{"properties":{"repo_path":{"title":"Repo Path","type":"string"}},"required":["repo_path"],"title":"GitReset","type":"object"}', '2025-05-23 16:53:37.081053', 'admin', '2025-05-23 16:53:37.081053', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837508810248192, 'mcp-git', '1.9.1', 'git_create_branch', 'Creates a new branch from an optional base branch', '{"properties":{"repo_path":{"title":"Repo Path","type":"string"},"branch_name":{"title":"Branch Name","type":"string"},"base_branch":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null,"title":"Base Branch"}},"required":["repo_path","branch_name"],"title":"GitCreateBranch","type":"object"}', '2025-05-23 16:53:37.088245', 'admin', '2025-05-23 16:53:37.088245', 'admin');
