INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541391601664, 'Notion MCP Server', '1.0.0', 'notion_append_block_children', 'Append new children blocks to a specified parent block in Notion. Requires insert content capabilities. You can optionally specify the ''after'' parameter to append after a certain block.', '{"type":"object","properties":{"block_id":{"type":"string","description":"The ID of the parent block.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"children":{"type":"array","description":"Array of block objects to append. Each block must follow the Notion block schema.","items":{"type":"object","description":"A Notion block object.","properties":{"object":{"type":"string","description":"Should be \u0027block\u0027.","enum":["block"]},"type":{"type":"string","description":"Type of the block. Possible values include \u0027paragraph\u0027, \u0027heading_1\u0027, \u0027heading_2\u0027, \u0027heading_3\u0027, \u0027bulleted_list_item\u0027, \u0027numbered_list_item\u0027, \u0027to_do\u0027, \u0027toggle\u0027, \u0027child_page\u0027, \u0027child_database\u0027, \u0027embed\u0027, \u0027callout\u0027, \u0027quote\u0027, \u0027equation\u0027, \u0027divider\u0027, \u0027table_of_contents\u0027, \u0027column\u0027, \u0027column_list\u0027, \u0027link_preview\u0027, \u0027synced_block\u0027, \u0027template\u0027, \u0027link_to_page\u0027, \u0027audio\u0027, \u0027bookmark\u0027, \u0027breadcrumb\u0027, \u0027code\u0027, \u0027file\u0027, \u0027image\u0027, \u0027pdf\u0027, \u0027video\u0027. Not all types are supported for creation via API."},"paragraph":{"type":"object","description":"Paragraph block object.","properties":{"rich_text":{"type":"array","description":"Array of rich text objects representing the comment content.","items":{"type":"object","description":"A rich text object.","properties":{"type":{"type":"string","description":"The type of this rich text object. Possible values: text, mention, equation.","enum":["text","mention","equation"]},"text":{"type":"object","description":"Object containing text content and optional link info. Required if type is \u0027text\u0027.","properties":{"content":{"type":"string","description":"The actual text content."},"link":{"type":"object","description":"Optional link object with a \u0027url\u0027 field. Do NOT provide a NULL value, just ignore this field no link.","properties":{"url":{"type":"string","description":"The URL the text links to."}}}}},"mention":{"type":"object","description":"Mention object if type is \u0027mention\u0027. Represents an inline mention of a database, date, link preview, page, template mention, or user.","properties":{"type":{"type":"string","description":"The type of the mention.","enum":["database","date","link_preview","page","template_mention","user"]},"database":{"type":"object","description":"Database mention object. Contains a database reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned database.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"date":{"type":"object","description":"Date mention object, containing a date property value object.","properties":{"start":{"type":"string","description":"An ISO 8601 formatted start date or date-time."},"end":{"type":["string","null"],"description":"An ISO 8601 formatted end date or date-time, or null if not a range."},"time_zone":{"type":["string","null"],"description":"Time zone information for start and end. If null, times are in UTC."}},"required":["start"]},"link_preview":{"type":"object","description":"Link Preview mention object, containing a URL for the link preview.","properties":{"url":{"type":"string","description":"The URL for the link preview."}},"required":["url"]},"page":{"type":"object","description":"Page mention object, containing a page reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned page.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"template_mention":{"type":"object","description":"Template mention object, can be a template_mention_date or template_mention_user.","properties":{"type":{"type":"string","enum":["template_mention_date","template_mention_user"],"description":"The template mention type."},"template_mention_date":{"type":"string","enum":["today","now"],"description":"For template_mention_date type, the date keyword."},"template_mention_user":{"type":"string","enum":["me"],"description":"For template_mention_user type, the user keyword."}}},"user":{"type":"object","description":"User mention object, contains a user reference.","properties":{"object":{"type":"string","description":"Should be \u0027user\u0027.","enum":["user"]},"id":{"type":"string","description":"The ID of the user.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["object","id"]}},"required":["type"],"oneOf":[{"required":["database"]},{"required":["date"]},{"required":["link_preview"]},{"required":["page"]},{"required":["template_mention"]},{"required":["user"]}]},"equation":{"type":"object","description":"Equation object if type is \u0027equation\u0027. Represents an inline LaTeX equation.","properties":{"expression":{"type":"string","description":"LaTeX string representing the inline equation."}},"required":["expression"]},"annotations":{"type":"object","description":"Styling information for the text. By default, give nothing for default text.","properties":{"bold":{"type":"boolean"},"italic":{"type":"boolean"},"strikethrough":{"type":"boolean"},"underline":{"type":"boolean"},"code":{"type":"boolean"},"color":{"type":"string","description":"Colo