INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541479682048, 'Notion MCP Server', '1.0.0', 'notion_retrieve_block_children', 'Retrieve the children of a block', '{"type":"object","properties":{"block_id":{"type":"string","description":"The ID of the block.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"start_cursor":{"type":"string","description":"Pagination cursor for next page of results"},"page_size":{"type":"number","description":"Number of results per page (max 100)"},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["block_id"]}', '2025-05-23 16:53:44.877557', 'admin', '2025-05-23 16:53:44.877557', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541534208000, 'Notion MCP Server', '1.0.0', 'notion_update_block', 'Update the content of a block in Notion based on its type. The update replaces the entire value for a given field.', '{"type":"object","properties":{"block_id":{"type":"string","description":"The ID of the block to update.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"block":{"type":"object","description":"The updated content for the block. Must match the block\u0027s type schema."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["block_id","block"]}', '2025-05-23 16:53:44.890116', 'admin', '2025-05-23 16:53:44.890116', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541563568128, 'Notion MCP Server', '1.0.0', 'notion_update_page_properties', 'Update properties of a page or an item in a Notion database', '{"type":"object","properties":{"page_id":{"type":"string","description":"The ID of the page or database item to update.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"properties":{"type":"object","description":"Properties to update. These correspond to the columns or fields in the database."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["page_id","properties"]}', '2025-05-23 16:53:44.897293', 'admin', '2025-05-23 16:53:44.897293', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541597122560, 'Notion MCP Server', '1.0.0', 'notion_retrieve_user', 'Retrieve a specific user by user_id in Notion. **Note:** This function requires upgrading to the Notion Enterprise plan and using an Organization API key to avoid permission errors.', '{"type":"object","properties":{"user_id":{"type":"string","description":"The ID of the user to retrieve.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["user_id"]}', '2025-05-23 16:53:44.904791', 'admin', '2025-05-23 16:53:44.904791', 'admin');
