tring","description":"An ISO 8601 formatted start date or date-time."},"end":{"type":["string","null"],"description":"An ISO 8601 formatted end date or date-time, or null if not a range."},"time_zone":{"type":["string","null"],"description":"Time zone information for start and end. If null, times are in UTC."}},"required":["start"]},"link_preview":{"type":"object","description":"Link Preview mention object, containing a URL for the link preview.","properties":{"url":{"type":"string","description":"The URL for the link preview."}},"required":["url"]},"page":{"type":"object","description":"Page mention object, containing a page reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned page.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"template_mention":{"type":"object","description":"Template mention object, can be a template_mention_date or template_mention_user.","properties":{"type":{"type":"string","enum":["template_mention_date","template_mention_user"],"description":"The template mention type."},"template_mention_date":{"type":"string","enum":["today","now"],"description":"For template_mention_date type, the date keyword."},"template_mention_user":{"type":"string","enum":["me"],"description":"For template_mention_user type, the user keyword."}}},"user":{"type":"object","description":"User mention object, contains a user reference.","properties":{"object":{"type":"string","description":"Should be \u0027user\u0027.","enum":["user"]},"id":{"type":"string","description":"The ID of the user.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["object","id"]}},"required":["type"],"oneOf":[{"required":["database"]},{"required":["date"]},{"required":["link_preview"]},{"required":["page"]},{"required":["template_mention"]},{"required":["user"]}]},"equation":{"type":"object","descript