INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541647454208, 'Notion MCP Server', '1.0.0', 'notion_retrieve_database', 'Retrieve a database in Notion', '{"type":"object","properties":{"database_id":{"type":"string","description":"The ID of the database to retrieve.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["database_id"]}', '2025-05-23 16:53:44.917224', 'admin', '2025-05-23 16:53:44.917224', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541676814336, 'Notion MCP Server', '1.0.0', 'notion_create_database_item', 'Create a new item (page) in a Notion database', '{"type":"object","properties":{"database_id":{"type":"string","description":"The ID of the database to add the item to.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"properties":{"type":"object","description":"Properties of the new database item. These should match the database schema."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["database_id","properties"]}', '2025-05-23 16:53:44.924384', 'admin', '2025-05-23 16:53:44.924384', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541706174464, 'Notion MCP Server', '1.0.0', 'notion_retrieve_comments', 'Retrieve a list of unresolved comments from a Notion page or block. Requires the integration to have ''read comment'' capabilities.', '{"type":"object","properties":{"block_id":{"type":"string","description":"The ID of the block or page whose comments you want to retrieve.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"start_cursor":{"type":"string","description":"If supplied, returns a page of results starting after the cursor."},"page_size":{"type":"number","description":"Number of comments to retrieve (max 100)."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["block_id"]}', '2025-05-23 16:53:44.931455', 'admin', '2025-05-23 16:53:44.931455', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837554498801664, 'Code Runner', '0.1.0', 'run-code', 'Run code snippet and return the result.', '{"type":"object","properties":{"code":{"type":"string","description":"Code Snippet"},"languageId":{"type":"string","enum":["javascript","php","python","perl","perl6","ruby","go","lua","groovy","powershell","bat","shellscript","fsharp","csharp","vbscript","typescript","coffeescript","scala","swift","julia","crystal","ocaml","r","applescript","clojure","racket","scheme","ahk","autoit","dart","haskell","nim","lisp","kit","v","sass","scss"],"description":"Language ID"}},"required":["code","languageId"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}', '2025-05-23 16:53:47.981505', 'admin', '2025-05-23 16:53:47.981505', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541580345344, 'Notion MCP Server', '1.0.0', 'notion_list_all_users', 'List all users in the Notion workspace. **Note:** This function requires upgrading to the Notion Enterprise plan and using an Organization API key to avoid permission errors.', '{"type":"object","properties":{"start_cursor":{"type":"string","description":"Pagination start cursor for listing users"},"page_size":{"type":"number","description":"Number of users to retrieve (max 100)"},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}}}', '2025-05-23 16:53:44.901341', 'admin', '2025-05-23 16:53:44.901341', 'admin');
