INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541660037120, 'Notion MCP Server', '1.0.0', 'notion_update_database', 'Update a database in Notion', '{"type":"object","properties":{"database_id":{"type":"string","description":"The ID of the database to update.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"title":{"type":"array","description":"An array of rich text objects that represents the title of the database that is displayed in the Notion UI.","items":{"type":"object","description":"A rich text object.","properties":{"type":{"type":"string","description":"The type of this rich text object. Possible values: text, mention, equation.","enum":["text","mention","equation"]},"text":{"type":"object","description":"Object containing text content and optional link info. Required if type is \u0027text\u0027.","properties":{"content":{"type":"string","description":"The actual text content."},"link":{"type":"object","description":"Optional link object with a \u0027url\u0027 field. Do NOT provide a NULL value, just ignore this field no link.","properties":{"url":{"type":"string","description":"The URL the text links to."}}}}},"mention":{"type":"object","description":"Mention object if type is \u0027mention\u0027. Represents an inline mention of a database, date, link preview, page, template mention, or user.","properties":{"type":{"type":"string","description":"The type of the mention.","enum":["database","date","link_preview","page","template_mention","user"]},"database":{"type":"object","description":"Database mention object. Contains a database reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned database.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"date":{"type":"object","description":"Date mention object, containing a date property value object.","properties":{"start":{"type":"string","description":"An ISO 8601 formatted start date or date-time."},"end":{"type":["string","null"],"description":"An ISO 8601 formatted end date or date-time, or null if not a range."},"time_zone":{"type":["string","null"],"description":"Time zone information for start and end. If null, times are in UTC."}},"required":["start"]},"link_preview":{"type":"object","description":"Link Preview mention object, containing a URL for the link preview.","properties":{"url":{"type":"string","description":"The URL for the link preview."}},"required":["url"]},"page":{"type":"object","description":"Page mention object, containing a page reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned page.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"template_mention":{"type":"object","description":"Template mention object, can be a template_mention_date or template_mention_user.","properties":{"type":{"type":"string","enum":["template_mention_date","template_mention_user"],"description":"The template mention type."},"template_mention_date":{"type":"string","enum":["today","now"],"description":"For template_mention_date type, the date keyword."},"template_mention_user":{"type":"string","enum":["me"],"description":"For template_mention_user type, the user keyword."}}},"user":{"type":"object","description":"User mention object, contains a user reference.","properties":{"object":{"type":"string","description":"Should be \u0027user\u0027.","enum":["user"]},"id":{"type":"string","description":"The ID of the user.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["object","id"]}},"required":["type"],"oneOf":[{"required":["database"]},{"required":["date"]},{"required":["link_preview"]},{"required":["page"]},{"required":["template_mention"]},{"required":["user"]}]},"equation":{"type":"object","description":"Equation object if type is \u0027equation\u0027. Represents an inline LaTeX equation.","properties":{"expression":{"type":"string","description":"LaTeX string representing the inline equation."}},"required":["expression"]},"annotations":{"type":"object","description":"Styling information for the text. By default, give nothing for default text.","properties":{"bold":{"type":"boolean"},"italic":{"type":"boolean"},"strikethrough":{"type":"boolean"},"underline":{"type":"boolean"},"code":{"type":"boolean"},"color":{"type":"string","description":"Color for the text.","enum":["default","blue","blue_background","brown","brown_background","gray","gray_background","green","green_background","orange","orange_background","pink","pink_background","purple","purple_background","red","red_background","yellow","yellow_background"]}}},"href":{"type":"string","description":"The URL of any link or mention in this text, if any. Do NOT provide a NULL value, just ignore this field if there is no link or mention."},"plain_text":{"type":"string","description":"The plain text without annotations."}},"required":["type"]}},"description":{"type":"array","description":"An array of rich text objects that represents the description of the database that is displayed in the Notion UI.","items":{"type":"object","description":"A rich text object.","properties":{"type":{"type":"string","description":"The type of this rich text object. Possible values: text, mention, equation.","enum":["text","mention","equation"]},"text":{"type":"object","description":"Object containing text content and optional link info. Required if type is \u0027text\u0027.","properties":{"content":{"type":"string","description":"The actual text content."},"link":{"type":"object","description":"Optional link object with a \u0027url\u0027 field. Do NOT provide a NULL value, just ignore this field no link.","properties":{"url":{"type":"string","description":"The URL the text links to."}}}}},"mention":{"type":"object","description":"Mention object if type is \u0027mention\u0027. Represents an inline mention of a database, date, link preview, page, template mention, or user.","properties":{"type":{"type":"string","description":"The type of the mention.","enum":["database","date","link_preview","page","template_mention","user"]},"database":{"type":"object","description":"Database mention object. Contains a database reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned database.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"date":{"type":"object","description":"Date mention object, containing a date property value object.","properties":{"start":{"type":"string","description":"An ISO 8601 formatted start date or date-time."},"end":{"type":["string","null"],"description":"An ISO 8601 formatted end date or date-time, or null if not a range."},"time_zone":{"type":["string","null"],"description":"Time zone information for start and end. If null, times are in UTC."}},"required":["start"]},"link_preview":{"type":"object","description":"Link Preview mention object, containing a URL for the link preview.","properties":{"url":{"type":"string","description":"The URL for the link preview."}},"required":["url"]},"page":{"type":"object","description":"Page mention object, containing a page reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned page.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"template_mention":{"type":"object","description":"Template mention object, can be a template_mention_date or template_mention_user.","properties":{"type":{"type":"string","enum":["template_mention_date","template_mention_user"],"description":"The template mention type."},"template_mention_date":{"type":"string","enum":["today","now"],"description":"For template_mention_date type, the date keyword."},"template_mention_user":{"type":"string","enum":["me"],"description":"For template_mention_user type, the user keyword."}}},"user":{"type":"object","description":"User mention object, contains a user reference.","properties":{"object":{"type":"string","description":"Should be \u0027user\u0027.","enum":["user"]},"id":{"type":"string","description":"The ID of the user.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["object","id"]}},"required":["type"],"oneOf":[{"required":["database"]},{"required":["date"]},{"required":["link_preview"]},{"required":["page"]},{"required":["template_mention"]},{"required":["user"]}]},"equation":{"type":"object","description":"Equation object if type is \u0027equation\u0027. Represents an inline LaTeX equation.","properties":{"expression":{"type":"string","description":"LaTeX string representing the inline equation."}},"required":["expression"]},"annotations":{"type":"object","description":"Styling information for the text. By default, give nothing for default text.","properties":{"bold":{"type":"boolean"},"italic":{"type":"boolean"},"strikethrough":{"type":"boolean"},"underline":{"type":"boolean"},"code":{"type":"boolean"},"color":{"type":"string","description":"Color for the text.","enum":["default","blue","blue_background","brown","brown_background","gray","gray_background","green","green_background","orange","orange_background","pink","pink_background","purple","purple_background","red","red_background","yellow","yellow_background"]}}},"href":{"type":"string","description":"The URL of any link or mention in this text, if any. Do NOT provide a NULL value, just ignore this field if there is no link or mention."},"plain_text":{"type":"string","description":"The plain text without annotations."}},"required":["type"]}},"properties":{"type":"object","description":"The properties of a database to be changed in the request, in the form of a JSON object."},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["database_id"]}', '2025-05-23 16:53:44.920685', 'admin', '2025-05-23 16:53:44.920685', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541689397248, 'Notion MCP Server', '1.0.0', 'notion_create_comment', 'Create a comment in Notion. This requires the integration to have ''insert comment'' capabilities. You can either specify a page parent or a discussion_id, but not both.', '{"type":"object","properties":{"parent":{"type":"object","description":"Parent object that specifies the page to comment on. Must include a page_id if used.","properties":{"page_id":{"type":"string","description":"The ID of the page to comment on.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}}},"discussion_id":{"type":"string","description":"The ID of an existing discussion thread to add a comment to.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."},"rich_text":{"type":"array","description":"Array of rich text objects representing the comment content.","items":{"type":"object","description":"A rich text object.","properties":{"type":{"type":"string","description":"The type of this rich text object. Possible values: text, mention, equation.","enum":["text","mention","equation"]},"text":{"type":"object","description":"Object containing text content and optional link info. Required if type is \u0027text\u0027.","properties":{"content":{"type":"string","description":"The actual text content."},"link":{"type":"object","description":"Optional link object with a \u0027url\u0027 field. Do NOT provide a NULL value, just ignore this field no link.","properties":{"url":{"type":"string","description":"The URL the text links to."}}}}},"mention":{"type":"object","description":"Mention object if type is \u0027mention\u0027. Represents an inline mention of a database, date, link preview, page, template mention, or user.","properties":{"type":{"type":"string","description":"The type of the mention.","enum":["database","date","link_preview","page","template_mention","user"]},"database":{"type":"object","description":"Database mention object. Contains a database reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned database.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"date":{"type":"object","description":"Date mention object, containing a date property value object.","properties":{"start":{"type":"string","description":"An ISO 8601 formatted start date or date-time."},"end":{"type":["string","null"],"description":"An ISO 8601 formatted end date or date-time, or null if not a range."},"time_zone":{"type":["string","null"],"description":"Time zone information for start and end. If null, times are in UTC."}},"required":["start"]},"link_preview":{"type":"object","description":"Link Preview mention object, containing a URL for the link preview.","properties":{"url":{"type":"string","description":"The URL for the link preview."}},"required":["url"]},"page":{"type":"object","description":"Page mention object, containing a page reference with an \u0027id\u0027 field.","properties":{"id":{"type":"string","description":"The ID of the mentioned page.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["id"]},"template_mention":{"type":"object","description":"Template mention object, can be a template_mention_date or template_mention_user.","properties":{"type":{"type":"string","enum":["template_mention_date","template_mention_user"],"description":"The template mention type."},"template_mention_date":{"type":"string","enum":["today","now"],"description":"For template_mention_date type, the date keyword."},"template_mention_user":{"type":"string","enum":["me"],"description":"For template_mention_user type, the user keyword."}}},"user":{"type":"object","description":"User mention object, contains a user reference.","properties":{"object":{"type":"string","description":"Should be \u0027user\u0027.","enum":["user"]},"id":{"type":"string","description":"The ID of the user.It should be a 32-character string (excluding hyphens) formatted as 8-4-4-4-12 with hyphens (-)."}},"required":["object","id"]}},"required":["type"],"oneOf":[{"required":["database"]},{"required":["date"]},{"required":["link_preview"]},{"required":["page"]},{"required":["template_mention"]},{"required":["user"]}]},"equation":{"type":"object","description":"Equation object if type is \u0027equation\u0027. Represents an inline LaTeX equation.","properties":{"expression":{"type":"string","description":"LaTeX string representing the inline equation."}},"required":["expression"]},"annotations":{"type":"object","description":"Styling information for the text. By default, give nothing for default text.","properties":{"bold":{"type":"boolean"},"italic":{"type":"boolean"},"strikethrough":{"type":"boolean"},"underline":{"type":"boolean"},"code":{"type":"boolean"},"color":{"type":"string","description":"Color for the text.","enum":["default","blue","blue_background","brown","brown_background","gray","gray_background","green","green_background","orange","orange_background","pink","pink_background","purple","purple_background","red","red_background","yellow","yellow_background"]}}},"href":{"type":"string","description":"The URL of any link or mention in this text, if any. Do NOT provide a NULL value, just ignore this field if there is no link or mention."},"plain_text":{"type":"string","description":"The plain text without annotations."}},"required":["type"]}},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}},"required":["rich_text"]}', '2025-05-23 16:53:44.927174', 'admin', '2025-05-23 16:53:44.927174', 'admin');
INSERT INTO "mcp_tools" ("id", "server_name", "server_version", "tool_name", "tool_description", "tool_input_schema", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925837541722951680, 'Notion MCP Server', '1.0.0', 'notion_search', 'Search pages or databases by title in Notion', '{"type":"object","properties":{"query":{"type":"string","description":"Text to search for in page or database titles"},"filter":{"type":"object","description":"Filter results by object type (page or database)","properties":{"property":{"type":"string","description":"Must be \u0027object\u0027"},"value":{"type":"string","description":"Either \u0027page\u0027 or \u0027database\u0027"}}},"sort":{"type":"object","description":"Sort order of results","properties":{"direction":{"type":"string","enum":["ascending","descending"]},"timestamp":{"type":"string","enum":["last_edited_time"]}}},"start_cursor":{"type":"string","description":"Pagination start cursor"},"page_size":{"type":"number","description":"Number of results to return (max 100). "},"format":{"type":"string","enum":["json","markdown"],"description":"Specify the response format. \u0027json\u0027 returns the original data structure, \u0027markdown\u0027 returns a more readable format. Use \u0027markdown\u0027 when the user only needs to read the page and isn\u0027t planning to write or modify it. Use \u0027json\u0027 when the user needs to read the page with the intention of writing to or modifying it.","default":"markdown"}}}', '2025-05-23 16:53:44.935521', 'admin', '2025-05-23 16:53:44.935521', 'admin');
